  <script>
    const formatAED = value => value.toFixed(2) + " د.إ";
    const itemCount = document.getElementById("itemCount");
    const subtotalEl = document.getElementById("subtotal");
    const vatEl = document.getElementById("vat");
    const grandTotalEl = document.getElementById("grandTotal");
    const promoMessage = document.getElementById("promoMessage");
    let discountRate = 0;

    function updateTotals() {
      let subtotal = 0;
      let totalQuantity = 0;

      document.querySelectorAll(".cart-item").forEach(item => {
        const quantity = Number(item.querySelector(".quantity").textContent);
        const unitPrice = Number(item.dataset.price);
        const lineTotal = unitPrice * quantity;
        subtotal += lineTotal;
        totalQuantity += quantity;
        item.querySelector("[data-line-price]").textContent = formatAED(lineTotal);
      });

      const discountedSubtotal = subtotal * (1 - discountRate);
      const vat = discountedSubtotal * 0.05;
      const total = discountedSubtotal + vat;

      subtotalEl.textContent = formatAED(subtotal);
      vatEl.textContent = formatAED(vat);
      grandTotalEl.textContent = formatAED(total);
      itemCount.textContent = totalQuantity + (totalQuantity === 1 ? " منتج" : totalQuantity === 2 ? " منتجان" : " منتجات");
    }

    document.querySelectorAll(".cart-item").forEach(item => {
      item.querySelectorAll("[data-action]").forEach(button => {
        button.addEventListener("click", () => {
          const quantityEl = item.querySelector(".quantity");
          let quantity = Number(quantityEl.textContent);

          if (button.dataset.action === "increase") {
            quantity++;
          } else {
            quantity = Math.max(1, quantity - 1);
          }

          quantityEl.textContent = quantity;
          updateTotals();
        });
      });
    });

    document.getElementById("applyPromo").addEventListener("click", () => {
      const code = document.getElementById("promoCode").value.trim().toUpperCase();

      if (code === "FOOD10") {
        discountRate = 0.10;
        promoMessage.textContent = "تم تطبيق خصم 10% بنجاح";
        promoMessage.classList.remove("error");
      } else if (code === "GULF5") {
        discountRate = 0.05;
        promoMessage.textContent = "تم تطبيق خصم 5% بنجاح";
        promoMessage.classList.remove("error");
      } else {
        discountRate = 0;
        promoMessage.textContent = code ? "رمز الخصم غير صالح، حاول مرة أخرى" : "أدخل رمز الخصم أولًا";
        promoMessage.classList.toggle("error", Boolean(code));
      }

      updateTotals();
    });

    document.getElementById("placeOrder").addEventListener("click", event => {
      const button = event.currentTarget;
      const originalText = button.textContent;
      button.textContent = "جارٍ إرسال الطلب...";
      button.disabled = true;

      setTimeout(() => {
        button.textContent = "تم إرسال الطلب ✓";
        setTimeout(() => {
          button.textContent = originalText;
          button.disabled = false;
        }, 1700);
      }, 900);
    });

    updateTotals();
  </script>
